begin;
set local search_path=public,extensions;
select plan(30);

select ok((select count(*)=11 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname=any(array['service_skus','framework_agreements','framework_agreement_versions','provider_capacity_commitments','service_inventory_pools','service_reservations','service_provider_allocations','service_inventory_transactions','service_provider_consumptions','volume_rebate_versions','volume_rebate_accruals'])),'all volume procurement records exist');
select ok((select count(*)=11 and bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array['service_skus','framework_agreements','framework_agreement_versions','provider_capacity_commitments','service_inventory_pools','service_reservations','service_provider_allocations','service_inventory_transactions','service_provider_consumptions','volume_rebate_versions','volume_rebate_accruals'])),'RLS is enabled on every volume table');
select ok((select count(*)=11 from pg_policies where schemaname='public' and tablename=any(array['service_skus','framework_agreements','framework_agreement_versions','provider_capacity_commitments','service_inventory_pools','service_reservations','service_provider_allocations','service_inventory_transactions','service_provider_consumptions','volume_rebate_versions','volume_rebate_accruals'])),'every volume table has an explicit read policy');
select ok((select count(*)=3 and bool_and(p.prosecdef and p.proconfig::text like '%search_path=%') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['reserve_service_units','allocate_provider_from_pool','consume_service_units'])),'three volume commands are security definer with fixed search paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['reserve_service_units','allocate_provider_from_pool','consume_service_units'])and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'anonymous and service roles cannot execute volume commands');
select ok((select count(*)=3 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['reserve_service_units','allocate_provider_from_pool','consume_service_units'])),'authenticated receives explicit command execution');
select ok(not has_table_privilege('authenticated','public.service_inventory_pools','UPDATE')and not has_table_privilege('authenticated','public.service_reservations','INSERT')and not has_table_privilege('authenticated','public.service_provider_allocations','INSERT')and not has_table_privilege('authenticated','public.service_inventory_transactions','DELETE'),'direct capacity and economic mutations are denied');
select ok((select count(*)=7 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array['service_skus','framework_agreement_versions','service_provider_allocations','service_inventory_transactions','service_provider_consumptions','volume_rebate_versions','volume_rebate_accruals'])and t.tgname like '%_immutable'and not t.tgisinternal),'version and economic history records are immutable');
select ok(not exists(select 1 from information_schema.columns where table_schema='public' and table_name=any(array['service_skus','framework_agreement_versions','provider_capacity_commitments','service_inventory_pools','service_reservations','service_provider_allocations','service_inventory_transactions','service_provider_consumptions','volume_rebate_versions','volume_rebate_accruals'])and data_type in('real','double precision')),'volume quantities and money never use floating point');
select ok((select count(*)>=19 from information_schema.columns where table_schema='public' and table_name=any(array['service_skus','framework_agreement_versions','provider_capacity_commitments','service_inventory_pools','service_reservations','service_provider_allocations','service_inventory_transactions','service_provider_consumptions','volume_rebate_versions','volume_rebate_accruals'])and data_type='numeric'),'quantities and thresholds use exact numeric columns');
select ok((select count(*)>=5 from information_schema.columns where table_schema='public' and table_name=any(array['service_skus','provider_capacity_commitments','service_provider_allocations','service_provider_consumptions','volume_rebate_accruals'])and column_name like '%_minor'and data_type='bigint'),'monetary values use bigint minor units');
select ok((select count(*)=1 from pg_indexes where schemaname='public' and tablename='service_skus' and indexdef like '%WHERE (status = ''ACTIVE''%'),'only one active version exists for a SKU code');
select ok((select count(*)=1 from pg_constraint where conrelid='public.framework_agreement_versions'::regclass and contype='u'and pg_get_constraintdef(oid)like '%agreement_id, version%'),'framework agreement versions cannot duplicate a version');
select ok((select count(*)>=1 from pg_constraint where conrelid='public.framework_agreement_versions'::regclass and contype='c'and pg_get_constraintdef(oid)like '%minimum_commitment_units <= maximum_units%'),'minimum commitment cannot exceed negotiated maximum');
select ok((select count(*)>=1 from pg_constraint where conrelid='public.provider_capacity_commitments'::regclass and contype='c'and pg_get_constraintdef(oid)like '%committed_units%'and pg_get_constraintdef(oid)like '%consumed_units%'and pg_get_constraintdef(oid)like '%released_units%'and pg_get_constraintdef(oid)like '%capacity_units%'),'provider state totals cannot exceed contracted capacity');
select ok((select count(*)>=1 from pg_constraint where conrelid='public.service_inventory_pools'::regclass and contype='c'and pg_get_constraintdef(oid)like '%available_units%'and pg_get_constraintdef(oid)like '%reserved_units%'and pg_get_constraintdef(oid)like '%committed_units%'and pg_get_constraintdef(oid)like '%consumed_units%'and pg_get_constraintdef(oid)like '%released_units%'and pg_get_constraintdef(oid)like '%contracted_units%'),'pool state partition must equal contracted capacity');
select ok((select count(*)>=1 from pg_constraint where conrelid='public.service_reservations'::regclass and contype='c'and pg_get_constraintdef(oid)like '%consumed_units%'and pg_get_constraintdef(oid)like '%released_units%'and pg_get_constraintdef(oid)like '%reserved_units%'),'reservation cannot be overconsumed');
select ok((select count(*)=1 from pg_constraint where conrelid='public.service_provider_allocations'::regclass and contype='u'and pg_get_constraintdef(oid)like '%reservation_id, provider_commitment_id%'),'same provider commitment cannot be allocated twice to one reservation');
select ok((select count(*)=1 from pg_constraint where conrelid='public.service_provider_consumptions'::regclass and contype='u'and pg_get_constraintdef(oid)like '%allocation_id, idempotency_key%'),'provider consumption replay is unique');
select ok((select count(*)>=1 from pg_constraint where conrelid='public.volume_rebate_accruals'::regclass and contype='u'and pg_get_constraintdef(oid)like '%pool_id, rebate_version_id, provider_organization_id%'),'one rebate accrual exists per pool rule version and provider');
select ok((select pg_get_functiondef(p.oid)like '%for update%'and pg_get_functiondef(p.oid)like '%VOLUME_POOL_EXHAUSTED%'and pg_get_functiondef(p.oid)like '%available_units=available_units-p_units%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='reserve_service_units'),'reservation locks pool and atomically rejects exhaustion');
select ok((select pg_get_functiondef(p.oid)like '%RESERVATION_EXPIRY_EXCEEDS_POLICY%'and pg_get_functiondef(p.oid)like '%reservation_ttl%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='reserve_service_units'),'reservation enforces its versioned pool window and TTL');
select ok((select pg_get_functiondef(p.oid)like '%for update%'and pg_get_functiondef(p.oid)like '%PROVIDER_CAPACITY_EXCEEDED_OR_INELIGIBLE%'and pg_get_functiondef(p.oid)like '%RESERVATION_OVERALLOCATED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='allocate_provider_from_pool'),'provider allocation locks and prevents capacity and reservation over-allocation');
select ok((select pg_get_functiondef(p.oid)like '%PROVIDER_ALLOCATION_OVERCONSUMED%'and pg_get_functiondef(p.oid)like '%RESERVATION_OVERCONSUMED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='consume_service_units'),'consumption prevents provider and reservation overconsumption');
select ok((select pg_get_functiondef(p.oid)like '%service_provider_consumptions%'and pg_get_functiondef(p.oid)like '%service_inventory_transactions%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='consume_service_units'),'consumption writes immutable provider and pool events');
select ok((select count(*)=3 and bool_and(pg_get_functiondef(p.oid)like '%begin_volume_command%'and pg_get_functiondef(p.oid)like '%finish_volume_command%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['reserve_service_units','allocate_provider_from_pool','consume_service_units'])),'all sensitive volume commands are idempotent');
select ok((select pg_get_functiondef(p.oid)like '%volume.units_reserved%'and pg_get_functiondef(p.oid)like '%ServiceUnitReservedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='reserve_service_units'),'reservation emits audit and Outbox evidence');
select ok((select pg_get_functiondef(p.oid)like '%volume.provider_allocated%'and pg_get_functiondef(p.oid)like '%ProviderAllocatedFromPoolV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='allocate_provider_from_pool'),'provider allocation emits audit and Outbox evidence');
select ok((select pg_get_functiondef(p.oid)like '%volume.units_consumed%'and pg_get_functiondef(p.oid)like '%ServiceUnitConsumedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='consume_service_units'),'consumption emits audit and Outbox evidence');
select ok((select count(*)=3 from pg_indexes where schemaname='public'and indexname=any(array['inventory_pools_status_window_idx','reservations_client_status_idx','inventory_transactions_pool_time_idx'])),'operational pool, expiry and ledger indexes exist');

select * from finish();
rollback;
